class Solution {
public:
    bool isEscapePossible(vector<vector<int>>& blocked, vector<int>& source, vector<int>& target) {
        unordered_set<long long> blocked_set;
        for (const auto& b : blocked) {
            blocked_set.insert(((long long)b[0] << 32) | (unsigned int)b[1]);
        }
        long long max_visit = (long long)blocked.size() * ((long long)blocked.size() - 1) / 2;

        auto bfs = [&](long long start, long long dest) -> bool {
            unordered_set<long long> visited;
            visited.insert(start);
            queue<long long> q;
            q.push(start);
            int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

            while (!q.empty() && (long long)visited.size() <= max_visit) {
                long long curr = q.front();
                q.pop();
                if (curr == dest) return true;
                int r = curr >> 32;
                int c = curr & 0xFFFFFFFF;
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dirs[d][0], nc = c + dirs[d][1];
                    if (nr >= 0 && nr < 1000000 && nc >= 0 && nc < 1000000) {
                        long long nxt = ((long long)nr << 32) | (unsigned int)nc;
                        if (blocked_set.find(nxt) == blocked_set.end() && visited.find(nxt) == visited.end()) {
                            visited.insert(nxt);
                            q.push(nxt);
                        }
                    }
                }
            }
            return (long long)visited.size() > max_visit;
        };

        long long s = ((long long)source[0] << 32) | (unsigned int)source[1];
        long long t = ((long long)target[0] << 32) | (unsigned int)target[1];
        return bfs(s, t) && bfs(t, s);
    }
};

class Solution {
    public boolean isEscapePossible(int[][] blocked, int[] source, int[] target) {
        Set<Long> blockedSet = new HashSet<>();
        for (int[] b : blocked) {
            blockedSet.add((((long) b[0]) << 32) | (b[1] & 0xFFFFFFFFL));
        }
        long maxVisit = ((long) blocked.length) * (blocked.length - 1) / 2;

        long s = (((long) source[0]) << 32) | (source[1] & 0xFFFFFFFFL);
        long t = (((long) target[0]) << 32) | (target[1] & 0xFFFFFFFFL);

        return bfs(s, t, blockedSet, maxVisit) && bfs(t, s, blockedSet, maxVisit);
    }

    private boolean bfs(long start, long dest, Set<Long> blockedSet, long maxVisit) {
        Set<Long> visited = new HashSet<>();
        visited.add(start);
        Queue<Long> q = new ArrayDeque<>();
        q.add(start);
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!q.isEmpty() && visited.size() <= maxVisit) {
            long curr = q.poll();
            if (curr == dest) return true;
            int r = (int) (curr >> 32);
            int c = (int) curr;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < 1000000 && nc >= 0 && nc < 1000000) {
                    long nxt = (((long) nr) << 32) | (nc & 0xFFFFFFFFL);
                    if (!blockedSet.contains(nxt) && visited.add(nxt)) {
                        q.add(nxt);
                    }
                }
            }
        }
        return visited.size() > maxVisit;
    }
}

var isEscapePossible = function(blocked, source, target) {
    const blockedSet = new Set();
    for (const [r, c] of blocked) {
        blockedSet.add(`${r},${c}`);
    }
    const maxVisit = Math.floor(blocked.length * (blocked.length - 1) / 2);

    const bfs = (start, dest) => {
        const visited = new Set();
        visited.add(`${start[0]},${start[1]}`);
        const q = [start];
        let head = 0;
        const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

        while (head < q.length && visited.size <= maxVisit) {
            const [r, c] = q[head++];
            if (r === dest[0] && c === dest[1]) return true;
            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < 1000000 && nc >= 0 && nc < 1000000) {
                    const key = `${nr},${nc}`;
                    if (!blockedSet.has(key) && !visited.has(key)) {
                        visited.add(key);
                        q.push([nr, nc]);
                    }
                }
            }
        }
        return visited.size > maxVisit;
    };

    return bfs(source, target) && bfs(target, source);
};
